  if (nextLpPickerWidth !== null) toSet["lpPickerWidth"] = nextLpPickerWidth;
  if (nextLpPickerHeight !== null) toSet["lpPickerHeight"] = nextLpPickerHeight;
  if (nextLpPickerOpacity !== null) toSet["lpPickerOpacity"] = nextLpPickerOpacity;
