    row.append(fav,tx,cat);
    row.onclick=function(e){
      a.runtime.sendMessage({type:"command-palette-open",url:r.url,currentTab:!e.ctrlKey&&!e.metaKey}).catch(function(){})
    };
    row.onmouseenter=function(){setActive(i)};
