function getHttpHostnameFromUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== "string") return "";
  try {
    const parsed = new URL(rawUrl);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return "";
    return parsed.hostname ? parsed.hostname.trim().toLowerCase() : "";
  } catch (err) {
    return "";
  }
}

function resolveContextMenuHostname(info, tab) {
  const candidates = [
    tab && typeof tab.url === "string" ? tab.url : "",
    info && typeof info.pageUrl === "string" ? info.pageUrl : "",
    info && typeof info.frameUrl === "string" ? info.frameUrl : "",
  ];
  for (const candidate of candidates) {
    const hostname = getHttpHostnameFromUrl(candidate);
    if (hostname) return hostname;
  }
  return "";
}

function domainExceptionPatternMatchesHostname(hostname, pattern) {
  const rawPattern =
    typeof pattern === "string" ? pattern.trim().toLowerCase() : "";
  if (!hostname || !rawPattern) return false;
  const normalizedPattern =
    typeof normalizeDomainExceptionEntry === "function"
      ? normalizeDomainExceptionEntry(rawPattern)
      : rawPattern;
  if (!normalizedPattern) return false;
  if (normalizedPattern === hostname) return true;
  if (!normalizedPattern.startsWith("*.")) return false;
  const base = normalizedPattern.slice(2);
  if (!base) return false;
  if (hostname === base) return true;
  return hostname.endsWith(`.${base}`);
}

function isHostnameExcludedByFloatingList(hostname, patterns) {
  const entries = Array.isArray(patterns) ? patterns : [];
  return entries.some((pattern) =>
    domainExceptionPatternMatchesHostname(hostname, pattern),
  );
}

async function notifyFloatingDomainException(message) {
  const shown = await showInPageToast(message);
  if (shown) return;
  if (!lpApi.notifications || !lpApi.notifications.create) return;
  const iconUrl =
    lpApi.runtime && lpApi.runtime.getURL
      ? lpApi.runtime.getURL("icons/icon-default-32.png")
      : "icons/icon-default-32.png";
  const notificationId = `local-pocket-floating-domain-${Date.now()}`;
  try {
    const maybePromise = lpApi.notifications.create(notificationId, {
      type: "basic",
      title: "Floating button",
      message,
      iconUrl,
    });
    if (maybePromise && typeof maybePromise.then === "function") {
      maybePromise.catch(() => { });
    }
  } catch (err) {
    return;
  }
  setTimeout(() => {
    try {
      const maybePromise = lpApi.notifications.clear(notificationId);
      if (maybePromise && typeof maybePromise.then === "function") {
        maybePromise.catch(() => { });
      }
    } catch (err) {
      // ignore clear errors
    }
  }, 2500);
}

async function handleFloatingDomainExceptionContextMenu(info, tab, action) {
  const mode = action === "remove" ? "remove" : "add";
  const hostname = resolveContextMenuHostname(info, tab);
  if (!hostname) {
    await notifyFloatingDomainException("Open an HTTP/HTTPS page first.");
    return;
  }
  const normalizedHost =
    typeof normalizeDomainExceptionEntry === "function"
      ? normalizeDomainExceptionEntry(hostname)
      : hostname;
  if (!normalizedHost || normalizedHost.startsWith("*.")) {
    await notifyFloatingDomainException("Failed to detect a valid domain.");
    return;
  }

  const settings = await getSettings();
  const currentList = Array.isArray(settings.floatingButtonDomainExceptions)
    ? settings.floatingButtonDomainExceptions.slice()
    : [];
  let nextList = currentList.slice();

  if (mode === "add") {
    if (isHostnameExcludedByFloatingList(normalizedHost, currentList)) {
      await notifyFloatingDomainException(
        `Floating already hidden on ${normalizedHost}`,
      );
      return;
    }
    nextList.push(normalizedHost);
  } else {
    nextList = currentList.filter(
      (pattern) =>
        !domainExceptionPatternMatchesHostname(normalizedHost, pattern),
    );
    if (nextList.length === currentList.length) {
      await notifyFloatingDomainException(
        `No floating exception for ${normalizedHost}`,
      );
      return;
    }
  }

  const normalizedList =
    typeof normalizeDomainExceptionList === "function"
      ? normalizeDomainExceptionList(nextList)
      : Array.from(new Set(nextList));
  await setSettings({ floatingButtonDomainExceptions: normalizedList });
  if (mode === "add") {
    await notifyFloatingDomainException(`Floating hidden on ${normalizedHost}`);
    return;
  }
  await notifyFloatingDomainException(`Floating enabled on ${normalizedHost}`);
}

let selectionSearchContextMenuMap = new Map();

function normalizeSelectionSearchMenuId(id) {
  const raw = typeof id === "string" ? id.trim() : "";
  const cleaned = raw.replace(/[^a-z0-9_-]/gi, "").slice(0, 40);
  return cleaned || String(Date.now());
}

function buildSelectionSearchUrl(entry, selectionText) {
  const query = String(selectionText || "").trim();
  if (!query) return "";
  if (!entry || !entry.type) return "";
  if (entry.type === "open-link") {
    try {
      if (/^https?:\/\//i.test(query)) {
        return new URL(query).toString();
      }
      return new URL(`https://${query}`).toString();
    } catch (_err) {
      return "";
    }
  }
  if (entry.type === "engine") {
    const rawUrl = entry.url ? String(entry.url) : "";
    if (!rawUrl) return "";
    const encoded = encodeURIComponent(query);
    if (/%s/i.test(rawUrl)) return rawUrl.replace(/%s/gi, encoded);
    if (/\{searchTerms\}/i.test(rawUrl)) return rawUrl.replace(/\{searchTerms\}/gi, encoded);
    return rawUrl + encoded;
  }
  return "";
}

async function createContextMenu() {
  if (!lpApi.contextMenus) return;
  try {
    if (lpApi.contextMenus.removeAll) {
      await lpApi.contextMenus.removeAll();
    }
  } catch (err) {
    lpWarn("Failed to clear old context menus", err);
  }
  try {
    /*
    lpApi.contextMenus.create({
      id: CONTEXT_MENU_ID_SAVE_TO_POCKET,
      title: "Add to Pocket",
      contexts: ["page", "link"],
    });
    */
    lpApi.contextMenus.create({
      id: CONTEXT_MENU_ID_FLOATING_ROOT,
      title: "Floating button",
      contexts: CONTEXT_MENU_WEB_CONTEXTS,
    });
    lpApi.contextMenus.create({
      id: CONTEXT_MENU_ID_FLOATING_ADD_DOMAIN,
      parentId: CONTEXT_MENU_ID_FLOATING_ROOT,
      title: "Hide on this domain",
      contexts: CONTEXT_MENU_WEB_CONTEXTS,
    });
    lpApi.contextMenus.create({
      id: CONTEXT_MENU_ID_FLOATING_REMOVE_DOMAIN,
      parentId: CONTEXT_MENU_ID_FLOATING_ROOT,
      title: "Remove domain exception",
      contexts: CONTEXT_MENU_WEB_CONTEXTS,
    });
    lpApi.contextMenus.create({
      id: CONTEXT_MENU_ID_SET_THUMBNAIL,
      title: "Set as thumbnail for saved page",
      contexts: ["image"],
    });
    lpApi.contextMenus.create({
      id: CONTEXT_MENU_ID_SET_CATEGORY_ICON,
      title: "Set as category icon",
      contexts: ["image"],
    });
    const settings = await getSettings();
    selectionSearchContextMenuMap = new Map();
    const selectionMenu = settings && settings.selectionSearchContextMenu
      ? settings.selectionSearchContextMenu
      : { enabled: false };
    if (selectionMenu && selectionMenu.enabled === true) {
      const rootTitle = selectionMenu.title && String(selectionMenu.title).trim()
        ? String(selectionMenu.title).trim()
        : "Search for \"%s\"";
      lpApi.contextMenus.create({
        id: CONTEXT_MENU_ID_SELECTION_ROOT,
        title: rootTitle,
        contexts: ["selection"],
      });
      const engines = Array.isArray(settings.selectionSearchEnginesList)
        ? settings.selectionSearchEnginesList
        : [];
      engines.forEach((entry) => {
        if (!entry || entry.showContextMenu !== true) return;
        if (entry.type === "separator") {
          lpApi.contextMenus.create({
            id: `${CONTEXT_MENU_ID_SELECTION_PREFIX}sep-${normalizeSelectionSearchMenuId(entry.id || "")}`,
            type: "separator",
            parentId: CONTEXT_MENU_ID_SELECTION_ROOT,
            contexts: ["selection"],
          });
          return;
        }
        if (entry.type === "group") {
          lpApi.contextMenus.create({
            id: `${CONTEXT_MENU_ID_SELECTION_PREFIX}grp-${normalizeSelectionSearchMenuId(entry.id || "")}`,
            title: entry.name ? String(entry.name) : "Group",
            parentId: CONTEXT_MENU_ID_SELECTION_ROOT,
            contexts: ["selection"],
            enabled: false,
          });
          return;
        }
        const id = normalizeSelectionSearchMenuId(entry.id || "");
        const menuId = `${CONTEXT_MENU_ID_SELECTION_PREFIX}${id}`;
        selectionSearchContextMenuMap.set(menuId, entry);
        lpApi.contextMenus.create({
          id: menuId,
          title: entry.name ? String(entry.name) : "Search",
          parentId: CONTEXT_MENU_ID_SELECTION_ROOT,
          contexts: ["selection"],
        });
      });
    }
  } catch (err) {
    lpErr("Failed to create context menu", err);
  }
}

